"use client";

import { useEffect } from "react";
import { toast } from "sonner";

const SW_URL = "/sw.js";
const UPDATE_INTERVAL_MS = 60 * 60 * 1000;

const MESSAGES = {
  fr: { text: "Une nouvelle version du site est disponible.", action: "Actualiser" },
  en: { text: "A new version of the site is available.", action: "Refresh" },
  es: { text: "Hay una nueva versión del sitio disponible.", action: "Actualizar" },
} as const;

type SupportedLocale = keyof typeof MESSAGES;

/**
 * Registers the PWA service worker (generated by next-pwa, production only) and keeps
 * it healthy:
 * - never registers in development (next-pwa is disabled there, `/sw.js` does not exist)
 *   and removes a worker left over by an earlier production run on the same origin, which
 *   otherwise tries to update itself against a 404;
 * - every update check is caught: a transient 404/offline during a deploy must not
 *   surface as an unhandled rejection;
 * - when a new worker takes control (skipWaiting + clientsClaim) the user is offered a
 *   refresh instead of being reloaded under their feet.
 */
export function ServiceWorkerRegistration({ locale = "fr" }: { locale?: string }) {
  useEffect(() => {
    if (!("serviceWorker" in navigator)) return;

    if (process.env.NODE_ENV !== "production") {
      navigator.serviceWorker
        .getRegistrations()
        .then((registrations) =>
          Promise.all(registrations.map((registration) => registration.unregister())),
        )
        .catch(() => undefined);
      return;
    }

    const messages = MESSAGES[(locale in MESSAGES ? locale : "fr") as SupportedLocale];
    const hadController = Boolean(navigator.serviceWorker.controller);
    let notified = false;
    let cancelled = false;
    let registration: ServiceWorkerRegistration | undefined;

    const checkForUpdate = () => {
      if (!registration || !navigator.onLine) return;
      registration.update().catch(() => {
        // sw.js briefly unavailable (deploy in progress, flaky network): retry on the next tick.
      });
    };

    const onControllerChange = () => {
      if (!hadController || notified) return;
      notified = true;
      toast(messages.text, {
        duration: Infinity,
        action: { label: messages.action, onClick: () => window.location.reload() },
      });
    };

    const onVisible = () => {
      if (document.visibilityState === "visible") checkForUpdate();
    };

    const register = async () => {
      try {
        registration = await navigator.serviceWorker.register(SW_URL, {
          scope: "/",
          updateViaCache: "none",
        });
        if (cancelled) return;
        checkForUpdate();
      } catch (error) {
        console.warn("[pwa] service worker registration failed", error);
      }
    };

    navigator.serviceWorker.addEventListener("controllerchange", onControllerChange);
    document.addEventListener("visibilitychange", onVisible);
    const interval = window.setInterval(checkForUpdate, UPDATE_INTERVAL_MS);

    const start = () => {
      if ("requestIdleCallback" in window) window.requestIdleCallback(() => void register());
      else setTimeout(() => void register(), 1000);
    };
    if (document.readyState === "complete") start();
    else window.addEventListener("load", start, { once: true });

    return () => {
      cancelled = true;
      window.clearInterval(interval);
      window.removeEventListener("load", start);
      document.removeEventListener("visibilitychange", onVisible);
      navigator.serviceWorker.removeEventListener("controllerchange", onControllerChange);
    };
  }, [locale]);

  return null;
}
